module flight_optimizer (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] adj_flat,  // Flattened 8x8 adjacency matrix\n    output reg [2:0] min_diameter,\n    output reg [2:0] remove_u,\n    output reg [2:0] remove_v,\n    output reg [2:0] add_u,\n    output reg [2:0] add_v,\n    output reg done\n);\n\n    // State declarations\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] INIT         = 4'd1;\n    localparam [3:0] FIND_EDGE    = 4'd2;\n    localparam [3:0] REMOVE_EDGE  = 4'd3;\n    localparam [3:0] FIND_COMP    = 4'd4;\n    localparam [3:0] BFS1_START   = 4'd5;\n    localparam [3:0] BFS1_LOOP    = 4'd6;\n    localparam [3:0] BFS2_START   = 4'd7;\n    localparam [3:0] BFS2_LOOP    = 4'd8;\n    localparam [3:0] CALC_STATS   = 4'd9;\n    localparam [3:0] UPDATE_BEST  = 4'd10;\n    localparam [3:0] RESTORE_EDGE = 4'd11;\n    localparam [3:0] FINALIZE     = 4'd12;\n\n    reg [3:0] state, next_state;\n    reg [63:0] adj_reg, temp_adj;\n    reg [2:0] edge_i, edge_j;\n    reg [2:0] best_diam;\n    reg [2:0] bu, bv, au, av;\n    reg [7:0] visited;\n    reg [2:0] queue [0:7];\n    reg [2:0] q_head, q_tail;\n    reg [2:0] current_node;\n    reg [2:0] max_dist;\n    reg [2:0] diam1, diam2, rad1, rad2;\n    reg [2:0] candidate_diam;\n    reg [7:0] dist [0:7];\n    integer i;\n\n    // Helper: Get edge from flat matrix\n    function get_edge;\n        input [2:0] row;\n        input [2:0] col;\n        input [63:0] mat;\n        begin\n            get_edge = mat[row*8 + col];\n        end\n    endfunction\n\n    // Helper: Set edge in matrix\n    function [63:0] set_edge;\n        input [2:0] row;\n        input [2:0] col;\n        input value;\n        input [63:0] mat;\n        reg [63:0] result;\n        begin\n            result = mat;\n            result[row*8 + col] = value;\n            result[col*8 + row] = value;\n            set_edge = result;\n        end\n    endfunction\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            min_diameter <= 3'd0;\n            remove_u <= 3'd0;\n            remove_v <= 3'd0;\n            add_u <= 3'd0;\n            add_v <= 3'd0;\n            best_diam <= 3'd7;\n            edge_i <= 3'd0;\n            edge_j <= 3'd1;\n            adj_reg <= 64'd0;\n            temp_adj <= 64'd0;\n            for (i=0; i<8; i=i+1) dist[i] <= 8'd0;\n        end\n        else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        adj_reg <= adj_flat;\n                        temp_adj <= adj_flat;\n                        edge_i <= 3'd0;\n                        edge_j <= 3'd1;\n                        best_diam <= 3'd7;\n                        state <= INIT;\n                    end\n                end\n\n                INIT: begin\n                    state <= FIND_EDGE;\n                end\n\n                FIND_EDGE: begin\n                    if (edge_i < 3'd7) begin\n                        if (edge_j < 3'd8) begin\n                            if (get_edge(edge_i, edge_j, adj_reg)) begin\n                                state <= REMOVE_EDGE;\n                            end\n                            else begin\n                                edge_j <= edge_j + 3'd1;\n                            end\n                        end\n                        else begin\n                            edge_i <= edge_i + 3'd1;\n                            edge_j <= edge_i + 3'd1;\n                        end\n                    end\n                    else state <= FINALIZE;\n                end\n\n                REMOVE_EDGE: begin\n                    temp_adj <= set_edge(edge_i, edge_j, 1'b0, temp_adj);\n                    visited <= 8'd0;\n                    diam1 <= 3'd0;\n                    diam2 <= 3'd0;\n                    state <= FIND_COMP;\n                end\n\n                FIND_COMP: begin\n                    // Simplified: Start BFS from node 0 to find first component\n                    q_head <= 3'd0;\n                    q_tail <= 3'd0;\n                    queue[0] <= 3'd0;\n                    visited[0] <= 1'b1;\n                    for (i=0; i<8; i=i+1) dist[i] <= 8'd0;\n                    max_dist <= 3'd0;\n                    state <= BFS1_START;\n                end\n\n                BFS1_START: begin\n                    if (q_head != q_tail) begin\n                        current_node <= queue[q_head];\n                        q_head <= q_head + 3'd1;\n                        state <= BFS1_LOOP;\n                    end\n                    else state <= CALC_STATS;\n                end\n\n                BFS1_LOOP: begin\n                    // Simplified neighbor processing\n                    for (i=0; i<8; i=i+1) begin\n                        if (!visited[i] && get_edge(current_node, i[2:0], temp_adj)) begin\n                            visited[i] <= 1'b1;\n                            queue[q_tail] <= i[2:0];\n                            q_tail <= q_tail + 3'd1;\n                            dist[i] <= dist[current_node] + 3'd1;\n                            if (dist[i] > max_dist) max_dist <= dist[i];\n                        end\n                    end\n                    state <= BFS1_START;\n                end\n\n                CALC_STATS: begin\n                    diam1 <= max_dist;\n                    candidate_diam <= diam1 + diam2;  // Simplified calculation\n                    state <= UPDATE_BEST;\n                end\n\n                UPDATE_BEST: begin\n                    if (candidate_diam < best_diam) begin\n                        best_diam <= candidate_diam;\n                        bu <= edge_i;\n                        bv <= edge_j;\n                        au <= 3'd0;  // Simplified edge addition\n                        av <= 3'd1;\n                    end\n                    state <= RESTORE_EDGE;\n                end\n\n                RESTORE_EDGE: begin\n                    temp_adj <= adj_reg;\n                    edge_j <= edge_j + 3'd1;\n                    if (edge_j >= 3'd7) begin\n                        edge_i <= edge_i + 3'd1;\n                        edge_j <= edge_i + 3'd2;\n                    end\n                    state <= FIND_EDGE;\n                end\n\n                FINALIZE: begin\n                    min_diameter <= best_diam;\n                    remove_u <= bu;\n                    remove_v <= bv;\n                    add_u <= au;\n                    add_v <= av;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule